/* First company-by-company editorial deep dive. No other profile is overridden. */
(()=>{
 const id='hindustan-unilever',c=window.COMPANIES.find(c=>c.id===id);
 const base='https://hul-performance-highlights.hul.co.in/performance-highlights-fy-2025-2026/segments/';
 const annual='https://www.hul.co.in/files/annual-report-2025-26-single-page.pdf';
 const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const ref=(url,label)=>`<a href="${url}" target="_blank" rel="noopener">${label} ↗</a>`;
 const note=(url,label,location='')=>`<p class="source-note">${ref(url,label)}${location?` · ${location}`:''}</p>`;
 c.description='Hindustan Unilever Limited, usually called HUL, develops and sells everyday consumer goods in India. It brings together brands such as Surf excel, Dove, Vim and Brooke Bond. The company behind the brands is what you research when you buy an HUL share.';
 c.money='HUL earns revenue by supplying consumer goods through shops, distributors, retail chains and online channels. Its earnings depend on what it receives for those goods, how much it sells, and the cost of ingredients, packaging, manufacturing, transport, advertising and running the business. A popular product needs to cover these costs before it contributes profit.';
 c.ownership='An HUL share is a small ownership interest in Hindustan Unilever Limited, the Indian listed company. It is not a separate share in Surf excel or Dove, and it does not give you a direct holding in every Unilever business worldwide. HUL belongs to the wider Unilever group, but you must read the Indian company’s own accounts and its relationships with group companies.';
 c.watch=[
 ['Are more goods being bought, or have prices changed?','Is sales growth coming from more goods sold, higher selling prices, or a different mix of products?'],
 ['How much of sales remains after operating costs?','Read margins with the explanation of material, distribution and advertising costs.'],
 ['Which categories are doing the work?','Compare Home Care, Beauty & Wellbeing, Personal Care and Foods separately, rather than judging HUL by one favourite brand.'],
 ['Are products reaching shoppers and being bought again?','Distribution creates access. Sustained consumer purchases are what keep the channel moving.'],
 ['Are you comparing the same business across periods?','Acquisitions, a demerger or a change in reporting scope can change the numbers even without a change in underlying demand.']
 ];
 window.COMPANY_RESEARCH_GUIDES[id]=[
 'Start with HUL’s underlying volume growth (UVG) and underlying sales growth (USG) commentary. UVG describes quantity growth on the company’s defined comparable basis; USG measures sales growth on its defined underlying basis. Read its pricing explanation rather than subtracting these percentages as if they were exact price figures. A lower pack price can support quantities while holding back sales growth.',
 'In results commentary, look for the reasons margins changed. A margin expresses a stated profit measure as a percentage of sales. Check ingredients and packaging, pricing and promotion, and advertising spending. Lower spending can improve a margin today without establishing that demand or the brand is stronger.',
 'Use the segment table at the end of this page and HUL’s category reviews. Compare sales with segment results using the same year and scope. A large category by sales need not have the highest margin. These figures describe business divisions; they do not tell you the profit of an individual Dove or Vim product.',
 'Read commentary on general trade (local shops), modern trade (organised retail chains), e-commerce and quick commerce. Ask whether growth reflects consumer purchases, changes in channel stock or a different channel mix. The brand directory establishes what is offered; it does not measure repeat purchases or stock sold through to households.',
 'Start with the reporting notes and continuing/discontinued operations. The FY 2025–26 continuing-operations segment figures here exclude ice cream. Consolidated accounts include HUL and its subsidiaries; standalone accounts cover the parent company alone. Read acquisition and related-party notes before explaining a change as ordinary growth.'
 ];
 c.risks=[
 ['Ingredients and packaging become more expensive','HUL may pay more to make each pack. Raising selling prices can protect earnings, but customers may buy less, choose cheaper products or switch brands. Check costs, pricing and quantities together.'],
 ['Consumers trade down or delay purchases','Even frequently purchased goods compete for household budgets. Shoppers may move to smaller packs or cheaper alternatives. A lower cash price for a pack is not necessarily a lower price per gram or millilitre.'],
 ['Competition weakens a brand’s appeal','Established rivals, local brands and newer specialist brands can compete for demand. More advertising or discounting may be needed to defend sales, leaving less profit from them. Brand familiarity alone does not prove pricing power.'],
 ['Products sell into the channel but not through it','Goods held by a distributor or retailer have not yet been used by a household. If channel stock builds faster than consumer demand, subsequent orders can slow. Read channel commentary rather than treating every sales increase as stronger household demand.'],
 ['The group relationship needs scrutiny','Read related-party transactions, brand and technology arrangements, and royalty disclosures. Payments and commitments involving group companies are part of understanding what remains for the Indian listed company and its shareholders.']
 ];
 c.update=['A useful HUL lesson: more volume does not always mean faster sales growth','In its FY 2025–26 Home Care review, HUL describes strong quantity growth alongside pricing actions that moderated underlying sales growth. Read this as an example of volume and price moving differently, rather than assuming all sales growth means stronger demand. The dated financial figures appear at the end of this page.'];
 c.question='Does the price printed on a Surf excel pack tell you HUL’s profit?';
 c.answer='No. The shopper’s price is not automatically HUL’s revenue: taxes, channel arrangements and discounts matter. HUL must then cover the costs of making, distributing and selling its goods. Its published segment results also group many products together; they do not disclose the profit of that individual pack.';
 c.products=c.products.map(([name,label])=>[name,['Clinic Plus','Sunsilk'].includes(name)?'Beauty & wellbeing · hair care':label]);
 c.sources[1]=['HUL annual report · business model and group accounts · FY 2025–26',annual];
 c.productNote='Official HUL brand directory reviewed on 29 October 2026. This list groups variants and pack sizes; Rexona soap and deodorant listings are combined. A brand-directory entry is not a separate profit disclosure.';
 c.reviewed='29 October 2026';c.checked='29 Oct 2026';
 c.sources.push(['HUL company overview','https://www.hul.co.in/our-company/']);
 window.COMPANY_OVERVIEWS[id]={customers:'Households use the products. HUL supplies a network of distributors, retailers, retail chains and online channels; the consumer and HUL’s immediate customer are not always the same person.',drivers:'How much is sold, the selling price, the kinds of products bought and the costs of making and selling them. Sales can grow while profit falls.'};
 const basics=`<section class="content-section company-primer" id="hul-basics"><div class="number">START FROM THE BASICS</div><h2>One company. Many brands. Everyday purchases.</h2><p>Think of the laundry detergent, shampoo or tea you replace when it runs out. HUL operates in <strong>fast-moving consumer goods (FMCG)</strong>: goods bought regularly for everyday use. Repeat purchases create an opportunity to earn sales again; they do not guarantee that customers stay with the same brand.</p><dl class="primer-definitions"><div><dt>Company → HUL</dt><dd>The business that brings together brands, product development, supply, marketing and sales. Its accounts combine much more than one product.</dd></div><div><dt>Brand → Surf excel</dt><dd>A name shoppers recognise. A brand can cover several products and pack sizes. A brand is not automatically a separate listed company.</dd></div><div><dt>Product → a detergent pack</dt><dd>The particular item bought. Its size, format and selling price can differ from another item carrying the same brand.</dd></div><div><dt>Business segment → Home Care</dt><dd>A group of related activities HUL reports together. Segment sales and results are not a separate profit statement for each brand.</dd></div></dl>${note('https://www.hul.co.in/brands/','HUL brand directory')}
 <h3>How a product reaches a household</h3><ol class="primer-route"><li><strong>Develop and source</strong><span>Decide what the product should do; arrange ingredients, packaging and production.</span></li><li><strong>Make and move</strong><span>Manufacture and move goods through warehouses and delivery networks.</span></li><li><strong>Supply the shopping channel</strong><span>Serve distributors, local shops, retail chains or online channels. The route differs by channel.</span></li><li><strong>The shopper buys and uses it</strong><span>The product is consumed and may be bought again. HUL still has to earn the next purchase.</span></li></ol><p>Goods move toward the shopper; payments flow through the relevant sales arrangements. <strong>A distributor buys and supplies goods to retailers. A retailer sells to the shopper.</strong> Neither is automatically owned by HUL.</p><details class="primer-detail"><summary>Why the pack’s price is not HUL’s profit</summary><p>The amount a shopper pays can include tax and income retained by the shopping channel. Discounts and trading arrangements also affect what HUL records as revenue. The company then incurs costs to make and sell its products. We do not know the exact split for an individual pack from the brand directory, so this page does not invent one.</p></details>${note(annual,'HUL annual report','Business model: printed pages 10–11; customer and channel discussion: printed pages 62–65')}
 <h3>Three different ways sales can change</h3><p>These are deliberately simplified examples of one imaginary, unchanged pack at an imaginary selling price to the company. They are not HUL prices, forecasts or reported results.</p><div class="primer-examples"><div><h4>Volume: sell more</h4><p>100 packs × ₹10 = ₹1,000.<br>110 packs × ₹10 = ₹1,100.</p><span>More of the same product was sold at the same price.</span></div><div><h4>Price: charge more</h4><p>100 packs × ₹10 = ₹1,000.<br>100 packs × ₹11 = ₹1,100.</p><span>Sales rose without more packs being sold.</span></div><div><h4>Mix: sell different things</h4><p>Customers choose a different balance of basic powders, liquids or premium products.</p><span>The average selling value and costs can change together.</span></div></div><p class="source-note">Teaching examples by Company Notebook. Real volume measures account for different products and pack sizes using the company’s definitions; they are not simply a count of every pack.</p></section>`;
 const special=`<section class="content-section company-primer" id="hul-specifics"><div class="number">WHAT IS DISTINCTIVE ABOUT HUL?</div><h2>Connect the familiar brands to four different businesses.</h2><p>HUL’s FY 2025–26 reviews organise the main consumer businesses below. These are reporting groups, not separate shares you can buy.</p><div class="primer-groups">${[
 ['Home Care','Laundry and household cleaning','Surf excel, Rin, Wheel, Comfort and Vim','Think about powder versus liquid, the amount bought, price changes and cleaning-product costs.','home-care'],
 ['Beauty & Wellbeing','Hair care, skin care, cosmetics and wellbeing','Clinic Plus, Sunsilk, TRESemmé, Vaseline, Lakmé and Minimalist','Think about specialised products, new formats, brand spending and whether higher-priced ranges earn additional profit.','beauty'],
 ['Personal Care','Skin cleansing, oral care and deodorants','Lux, Lifebuoy, Pears, Closeup and Rexona','Think about repeat use, soap versus bodywash and the balance between affordability, ingredient costs and pricing.','personal-care'],
 ['Foods','Tea, coffee, nutrition and packaged foods','Brooke Bond, Bru, Horlicks, Boost and Kissan','Think about tastes, household demand and ingredient costs. Tea, coffee and nutrition do not have identical economics.','foods']
 ].map(([name,meaning,brands,question,path])=>`<div><h3>${name}</h3><p>${meaning}.</p><p><strong>Recognisable examples:</strong> ${brands}.</p><p>${question}</p>${note(base+path+'/','HUL category review')}</div>`).join('')}</div><p>A brand can span categories: Dove hair-care products and Dove cleansing products need not sit in the same reporting segment. The numerical table also includes an “Others” row, including exports. The brand list alone cannot allocate every rupee of sales or profit to a segment.</p>
 <h3>What makes this business work?</h3>${[
 ['Reach and repeat purchases','Being available in shops and online can help a household buy again. But shelf access is different from consumer preference, and competitors also seek that space. Watch demand as well as distribution.'],
 ['Affordable and more expensive formats','HUL serves different budgets and product preferences. “Premiumisation” means a shift toward higher-priced or more specialised offerings. It may lift selling value, but extra production, marketing and distribution costs can offset the benefit.'],
 ['Which businesses are included can change','The FY 2025–26 report records the separation of the ice-cream business into Kwality Wall’s (India) Limited. A demerger separates a business into another company. Older associations with ice-cream brands should not be carried into HUL’s continuing-operations figures.']
 ].map(([h,p])=>`<div class="item"><h3>${h}</h3><p>${p}</p></div>`).join('')}${note(annual,'HUL annual report','Business model and category reviews; ice-cream demerger note 42 in standalone accounts')}
 <details class="primer-detail"><summary>Words you will meet in HUL’s results</summary><dl class="primer-glossary">${[
 ['Volume','Quantity sold on the stated reporting basis. Read the definition rather than equating it with the number of packs.'],
 ['Margin','A specified profit measure divided by sales, expressed as a percentage. Always identify which profit measure is used.'],
 ['Market share','The company’s portion of a defined market. Check whether the measure uses sales value or quantities and which category it covers.'],
 ['Pricing power','The ability to sustain prices without losing enough demand to undo the benefit. A well-known brand does not prove this ability.'],
 ['Consolidated versus standalone','Consolidated accounts include the company and its subsidiaries; standalone accounts cover the parent company alone.'],
 ['Working capital','Money involved in day-to-day stock, customer payments still due and supplier payments. Profit and cash collected need not arrive at the same time.'],
 ['Royalty and related-party transactions','A royalty is payment for agreed rights or resources such as a brand or technology. Related parties include group companies. Read the terms and amounts in the accounts instead of assuming all group dealings are free.']
 ].map(([term,meaning])=>`<div><dt>${term}</dt><dd>${meaning}</dd></div>`).join('')}</dl></details><p class="source-note">Learning explanations checked 29 October 2026 against the linked HUL sources. Category descriptions use the FY 2025–26 reporting structure; they do not establish a profit for any individual brand.</p></section>`;
 const ownership=`<details class="primer-detail"><summary>How is owning an HUL share different from buying its products?</summary><p>A product purchase pays for something you use. A share is an ownership interest whose market value can rise or fall. Buying an existing HUL share on the stock exchange normally means buying from another investor; that payment is not a new product sale for HUL.</p><p>A shareholder may receive a dividend if one is declared. A dividend is a payment to shareholders, not an automatic distribution of every rupee of company profit. The share can also be sold at a gain or a loss. Neither a dividend nor a positive return is guaranteed.</p><p>So there are two separate questions: “Do I understand HUL’s business?” and “Is this share worth the price I would pay?” This page builds the first understanding; it does not calculate a fair share price.</p>${note('https://investor.sebi.gov.in/understandings_shares.html','SEBI: understanding shares')}${note('https://investor.sebi.gov.in/securities-stockmarket.html','SEBI: primary and secondary markets')}</details>`;
 function numbers(){const f=window.COMPANY_FINANCIALS[id],home=f.rows.find(r=>r.name==='Home Care'),beauty=f.rows.find(r=>r.name==='Beauty & Wellbeing');return `<div class="primer-number-guide"><h3>Read these HUL figures in ordinary rupees</h3><p>For every ₹100 of reported segment sales, Home Care generated about <strong>₹${(home.profit/home.revenue*100).toFixed(2)}</strong> of segment result, compared with about <strong>₹${(beauty.profit/beauty.revenue*100).toFixed(2)}</strong> for Beauty & Wellbeing.</p><p>These are calculated as segment result ÷ segment revenue × 100 from the FY 2025–26 table above. They explain why a bigger business by sales can have a lower margin. They are <strong>not</strong> profit after tax, profit on a ₹100 retail pack, or returns you would earn on an HUL share.</p><p>Also keep the scope straight: this table is consolidated and covers continuing operations. It excludes the discontinued ice-cream business. Do not mix it with a standalone headline or assume the “Others” row is an unlisted brand’s profit.</p><details class="primer-detail"><summary>What to check next in HUL’s own accounts</summary><ul><li>Operating cash flow: did business operations generate cash, and how do inventory and customer/supplier payments explain any gap from profit?</li><li>Investment spending: what money went into facilities, technology or acquisitions?</li><li>Balance sheet and related-party notes: what obligations, cash holdings and group payments need understanding?</li><li>Share price and valuation: what expectations does today’s price assume? The business explanation alone does not answer this.</li></ul></details>${note(f.source,'Source of the calculation',esc(f.location))}</div>`}
 window.companyPrimer={render(company,slot){if(company.id!==id)return '';return slot==='basics'?basics:slot==='specifics'?special:slot==='ownership'?ownership:slot==='numbers'?numbers():'';},contents(company){return company.id===id?[['hul-basics','HUL from the basics'],['hul-specifics','HUL’s different businesses']]:[]}};
})();
